<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {beijingTime} from '@quote/archive-client';
import {BusinessOperations} from '../business-pending';
import type {PcApi} from '../api';
import {FinanceController,createFinanceState,financeBusy,financeDirty,financeOperationTarget,assertFinanceReceipt,termLabel,exceptionLabel,type FinanceTarget} from '../../../../packages/finance-client/src/index';
const props=defineProps<{api:Pick<PcApi,'get'|'post'|'write'>;userId:string;admin:boolean;locked?:boolean;initialTarget?:FinanceTarget}>();
const emit=defineEmits<{(e:'busy-changed',value:boolean):void;(e:'failure',value:unknown):void}>();
const state=reactive(createFinanceState(props.admin)),ack=ref(false),recovering=ref(false),notFound=ref(false),recoveryError=ref(''),storageError=ref('');
let operations:Pick<BusinessOperations,'pending'|'mutate'|'check'|'retry'>|null=null;
try{operations=reactive(new BusinessOperations(props.userId,async<T>(path:string)=>{const r=await props.api.get<T>(path);if(path.startsWith('/operations/')&&(r as any)?.status==='committed'&&operations?.pending)assertFinanceReceipt(operations.pending,(r as any).result);return r;},async<T>(path:string,method:'POST'|'PUT'|'PATCH',body:unknown,key:string)=>{const r=await props.api.write<T>(path,method,body,key);if(operations?.pending)assertFinanceReceipt(operations.pending,r);return r;},{getItem:key=>localStorage.getItem('finance-'+key),setItem:(key,value)=>localStorage.setItem('finance-'+key,value),removeItem:key=>localStorage.removeItem('finance-'+key)}));}catch(e){storageError.value=(e as Error).message;}
const controller=new FinanceController(path=>props.api.get(path),(label,path,body)=>{if(!operations)throw new Error(storageError.value||'待核对资料不可用，暂不能提交。');return operations.mutate(label,path,'POST',body);},state,e=>emit('failure',e));
const busy=computed(()=>financeBusy(state)||recovering.value),dirty=computed(()=>financeDirty(state)),locked=computed(()=>!!props.locked||busy.value),writeLocked=computed(()=>locked.value||!!operations?.pending||!!storageError.value||!!state.review),navigationLocked=computed(()=>locked.value||dirty.value||!!state.review||!!operations?.pending);
const exceptionWritable=computed(()=>!props.admin&&!!state.detail?.receivable.writable&&!!state.exceptions?.writable),termWritable=computed(()=>!props.admin&&!!state.context&&!!state.terms?.writable&&knownTerms.value),knownTerms=computed(()=>state.terms?.originalTermDays!=null&&state.terms?.effectiveTermDays!=null&&!!state.terms?.dueDate),pages=computed(()=>state.page?Math.max(1,Math.ceil(state.page.total/state.page.pageSize)):1),pendingException=computed(()=>state.exceptions?.items.find(e=>e.status==='pending_verification'));
watch(()=>busy.value||dirty.value||!!state.review||!!operations?.pending,value=>emit('busy-changed',value),{immediate:true,flush:'sync'});watch(()=>state.review,()=>{ack.value=false;});
function guard(work:()=>void){try{state.error='';work();}catch(e){state.error=(e as Error).message;}}
async function safely(work:()=>Promise<void>){try{await work();}catch(e){state.error=(e as Error).message;}}
async function openTarget(target:FinanceTarget){if(locked.value||dirty.value||state.review||operations?.pending)return;await safely(()=>controller.openTarget(target));}
async function openAfterRecovery(target:FinanceTarget){await controller.openTarget(target,true);state.notice=state.error?'原操作已确认提交；最新事实读取失败，请重新加载。':'原操作已确认提交，已重新读取账期、异常与余额。';}
async function refresh(){if(navigationLocked.value)return;await safely(()=>state.selected?controller.openTarget(state.selected):controller.bootstrap());}
async function commit(){if(locked.value||operations?.pending||storageError.value||!ack.value)return;try{await controller.commit();}catch{/* error and original pending remain visible */}}
async function recover(retry=false){if(locked.value||!operations?.pending)return;const original=operations.pending,target=financeOperationTarget(original);recovering.value=true;recoveryError.value='';try{const status=retry?(await operations.retry(),'committed'):await operations.check();notFound.value=status==='not_found';if(status==='committed'){controller.discard();if(target){if(target.hospitalId)await controller.hospitals();await openAfterRecovery(target);}await controller.reminders(state.page?.page||1);}}catch(e){recoveryError.value=(e as Error).message;emit('failure',e);}finally{recovering.value=false;}}
function beforeLeave(e:BeforeUnloadEvent){if(dirty.value||state.review||operations?.pending){e.preventDefault();e.returnValue='';}}
defineExpose({refresh,openTarget,openAfterRecovery,canLeave:()=>!busy.value&&!dirty.value&&!state.review&&!operations?.pending});
onMounted(async()=>{window.addEventListener('beforeunload',beforeLeave);await controller.bootstrap();if(props.initialTarget)await controller.openTarget(props.initialTarget);});
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeLeave);controller.dispose();emit('busy-changed',false);});
</script>
<template>
 <div class="finance-workspace">
  <p v-if="storageError" class="error" role="alert">{{storageError}}</p>
  <section v-if="operations?.pending" class="recovery" role="status"><strong>「{{operations.pending.label}}」结果待核对</strong><p>原请求内容和操作标识已保留，请先核对再处理其他事项。</p><div class="action-row"><button :disabled="locked" @click="recover()">核对操作结果</button><button v-if="notFound" :disabled="locked" @click="recover(true)">按原请求重新提交</button></div><p v-if="notFound">暂未找到提交结果；重新提交会沿用原输入和操作标识。</p><p v-if="recoveryError" class="error" role="alert">{{recoveryError}}</p></section>
  <div class="heading"><div><p class="eyebrow">到期跟进与账期管理</p><h1>{{state.mode==='hospital'?'医院默认账期':state.mode==='order'?'本单账期与异常':'到期与逾期提醒'}}</h1><p class="muted">到期当天起可查；异常暂停催收的订单仍保留在列表。微信提醒需真实配置与有效订阅。</p></div><span class="scope">{{admin?'全量业务 · 只读':'当前订单负责人处理'}}</span></div>
  <p v-if="state.error" class="error" role="alert">{{state.error}}</p><p v-if="state.notice" class="filter-note" role="status">{{state.notice}}</p><p v-if="busy" class="loading" role="status">正在读取或提交，请稍候…</p>
  <div v-if="dirty||state.review" class="unsaved" role="status"><span>有未保存的修改，请复核提交或放弃修改后再切换。</span><button :disabled="locked||!!operations?.pending" @click="controller.discard()">放弃本次修改</button></div>
  <div v-if="state.mode!=='reminders'" class="action-row"><button :disabled="navigationLocked" @click="safely(()=>controller.home())">← 返回到期列表</button><button :disabled="navigationLocked" @click="refresh">载入最新事实</button></div>
  <template v-if="state.mode==='reminders'">
   <p v-if="state.listError" class="error" role="alert">{{state.listError}} <button :disabled="locked" @click="controller.reminders()">重新查询</button></p>
   <template v-if="state.page"><div class="result-head"><strong>到期 / 逾期未收 {{state.page.total}} 单</strong><span>{{beijingTime(state.page.asOf)}} · 金额单位：元</span></div><div class="table-scroll"><table class="reminder-table"><thead><tr><th>医院 / 订单</th><th>应收 / 有效已收</th><th>未收余额</th><th>到期日 / 催收状态</th><th>订单负责人</th><th>操作</th></tr></thead><tbody><tr v-for="item in state.page.items" :key="item.id"><td><strong>{{item.hospitalName}}</strong><small>{{item.orderNo}}</small></td><td>{{item.amount}} / {{item.paid}}</td><td class="balance">{{item.balance}}</td><td>{{item.dueDate}}<small>{{item.dueState==='due'?'今日到期':'逾期未收'}}{{item.paused?' · 异常暂停催收':''}}</small></td><td>{{item.ownerName}}<small>{{item.writable&&!admin?'可处理':'只读查阅'}}</small></td><td><button :disabled="navigationLocked" @click="openTarget({orderId:item.orderId,receivableId:item.id})">查看账期 / 异常 →</button></td></tr><tr v-if="!state.page.items.length"><td colspan="6" class="empty">暂无到期未收应收。</td></tr></tbody></table></div><div class="pagination"><span>第 {{state.page.page}} / {{pages}} 页</span><button :disabled="navigationLocked||state.page.page<=1" @click="controller.reminders(state.page.page-1)">上一页</button><button :disabled="navigationLocked||state.page.page>=pages" @click="controller.reminders(state.page.page+1)">下一页</button></div></template>
   <section v-if="!admin" class="hospital-default"><h2>本人负责医院的默认账期</h2><p class="muted">仅之后新建订单采用新默认值，已有订单保持自己的账期快照。</p><p v-if="state.hospitalError" class="error">{{state.hospitalError}} <button :disabled="locked" @click="controller.hospitals()">重新读取医院</button></p><div class="hospital-links"><button v-for="h in state.hospitals" :key="h.id" :disabled="navigationLocked" @click="safely(()=>controller.openHospital(h.id))">{{h.name}} · 维护默认账期 →</button><p v-if="!state.hospitalsLoading&&!state.hospitals.length" class="muted">暂无本人负责的医院。</p></div></section>
   <p class="footnote">站内列表不代表微信消息已发送。自动催收从北京时间每日 09:00 起评估；结清、作废和异常暂停订单不自动催收。</p>
  </template>
  <template v-if="state.mode==='hospital'&&state.hospitalTerm"><h2>{{state.hospitals.find(h=>h.id===state.hospitalTerm?.hospitalId)?.name}}</h2><div class="facts"><div><span>当前医院默认账期</span><strong>{{termLabel(state.hospitalTerm.paymentTermDays)}}</strong></div></div><p class="filter-note">修改默认值仅影响之后新建订单，不改旧单账期、到期日或金额。</p><form class="term-form" @submit.prevent="guard(()=>controller.reviewHospital())"><label>新默认账期 / 自然日<input v-model="state.form.hospitalDays" inputmode="numeric" :disabled="writeLocked" maxlength="4" @input="controller.invalidateReview()" /></label><button class="primary" :disabled="writeLocked" type="submit">复核默认账期</button></form></template>
  <template v-if="state.mode==='order'&&state.terms&&state.context">
   <div class="order-heading"><p class="eyebrow">{{state.context.orderNo}}</p><h2>{{state.context.hospitalName}}</h2><p class="muted">实际接收 {{state.context.receivedDate}} · {{state.detail?.receivable.owner.name||'负责人见原单'}}{{termWritable||exceptionWritable?'':' · 只读'}}</p></div>
   <div v-if="state.detail" class="facts"><div><span>应收 / 元</span><strong>{{state.detail.receivable.amount}}</strong></div><div><span>有效已收 / 元</span><strong>{{state.detail.receivable.paid}}</strong></div><div><span>未收余额 / 元</span><strong>{{state.detail.receivable.balance}}</strong></div><div><span>催收状态</span><strong class="status-text">{{state.exceptions?.paused?'异常暂停催收':'按到期日与余额判断'}}</strong></div></div>
   <p v-if="!state.detail" class="filter-note">尚未形成应收。</p><p v-if="!termWritable&&!exceptionWritable" class="filter-note">本单只读。账期调整、异常登记及解除由当前订单负责销售处理；历史原账期未知时先核实当时约定。</p>
   <div class="finance-columns"><section><h2>本单账期</h2><dl class="panel-facts"><div><dt>原始账期快照</dt><dd>{{termLabel(state.terms.originalTermDays)}}</dd></div><div><dt>当前生效账期</dt><dd>{{termLabel(state.terms.effectiveTermDays)}}</dd></div><div><dt>当前到期日</dt><dd>{{state.terms.dueDate||'待核实'}}</dd></div></dl><p v-if="!knownTerms" class="filter-note">历史原账期待核实，不能通过单笔调整补成默认值或绕过核实。</p><form v-if="termWritable" class="term-form" @submit.prevent="guard(()=>controller.reviewTerm())"><label>新账期 / 自然日<input v-model="state.form.termDays" data-field="term-days" inputmode="numeric" maxlength="4" :disabled="writeLocked" @input="controller.invalidateReview()" /></label><label>调整原因<textarea v-model="state.form.termReason" data-field="term-reason" maxlength="500" :disabled="writeLocked" @input="controller.invalidateReview()"></textarea></label><p class="muted">从原实际接收日期重新计算到期日；金额、医院默认值不变，也不自动解除异常。</p><button class="primary" type="submit" :disabled="writeLocked">复核账期调整</button></form></section>
    <section><h2>取消 / 退款异常</h2><p class="muted">仅登记待处理事项并暂停催收，金额和结清状态保留。确需取消或退款时继续线下处理。</p><template v-if="pendingException"><p class="filter-note">{{exceptionLabel(pendingException.exceptionType)}}待核实 · 异常暂停催收</p><form v-if="exceptionWritable" class="term-form" @submit.prevent="guard(()=>controller.reviewResolve())"><label>线下核实结果<select v-model="state.form.verificationResult" :disabled="writeLocked" @change="state.form.resolveId=pendingException!.id;controller.invalidateReview()"><option value="">请选择核实结果</option><option value="continue_collection">确认仍需正常收款</option></select></label><label>解除原因<textarea v-model="state.form.resolveReason" maxlength="500" :disabled="writeLocked" @input="state.form.resolveId=pendingException!.id;controller.invalidateReview()"></textarea></label><button type="submit" :disabled="writeLocked">复核解除异常</button></form></template><form v-else-if="exceptionWritable" class="term-form" @submit.prevent="guard(()=>controller.reviewException())"><label>异常类型<select v-model="state.form.exceptionType" :disabled="writeLocked" @change="controller.invalidateReview()"><option value="cancellation">取消请求</option><option value="refund">退款请求</option></select></label><label>异常原因<textarea v-model="state.form.exceptionReason" maxlength="500" :disabled="writeLocked" @input="controller.invalidateReview()"></textarea></label><button type="submit" :disabled="writeLocked">复核异常登记</button></form></section></div>
   <section class="history"><h2>账期调整留痕</h2><p v-if="!state.terms.adjustments.length" class="muted">暂无账期调整，原始快照保留。</p><article v-for="a in state.terms.adjustments" :key="a.id"><strong>{{termLabel(a.beforeTermDays)}} → {{termLabel(a.afterTermDays)}}</strong><p>原始账期 {{termLabel(a.originalTermDays)}} · 到期日 {{a.beforeDueDate||'待核实'}} → {{a.afterDueDate||'待核实'}}</p><p>原因：{{a.reason}}</p><small>{{a.recordedByName}} · {{beijingTime(a.recordedAt)}}</small></article></section>
   <section class="history"><h2>异常登记与解除留痕</h2><p v-if="!state.exceptions?.items.length" class="muted">暂无异常记录。</p><article v-for="e in state.exceptions?.items" :key="e.id"><strong>{{exceptionLabel(e.exceptionType)}} · {{e.status==='pending_verification'?'待核实，暂停催收':'已解除，继续正常收款'}}</strong><p>原异常原因：{{e.reason}}</p><small>登记人 {{e.recordedByName}} · {{beijingTime(e.recordedAt)}}</small><template v-if="e.status==='resolved'"><p>核实结果：确认仍需正常收款</p><p>解除原因：{{e.resolveReason}}</p><small>解除人 {{e.resolvedByName}} · {{beijingTime(e.resolvedAt)}}</small></template></article></section>
  </template>
  <div v-if="state.review" class="review-overlay"><section class="review-dialog" role="dialog" aria-modal="true" aria-labelledby="finance-review-title"><p class="eyebrow">提交前复核</p><h2 id="finance-review-title">{{state.review.title}}</h2><dl class="review-facts"><template v-for="(fact,i) in state.review.facts" :key="i"><dt>{{fact[0]}}</dt><dd>{{fact[1]}}</dd></template></dl><p class="filter-note">{{state.review.impact}}</p><label class="review-ack"><input v-model="ack" type="checkbox" :disabled="busy" />已核对当前对象、变更内容和影响，确认按以上事实提交。</label><div class="action-row"><button :disabled="busy" @click="controller.invalidateReview()">返回修改</button><button class="primary" :disabled="locked||!!operations?.pending||!!storageError||!ack" @click="commit">{{state.working?'正在提交…':'确认操作'}}</button></div></section></div>
 </div>
</template>
<style scoped>
.reminder-table{min-width:1000px}.balance{font-weight:600}.hospital-default,.history{margin-top:34px;padding-top:24px;border-top:1px solid #dfe7e1}.hospital-links{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}.unsaved{display:flex;align-items:center;justify-content:space-between;gap:15px;background:#f7f2e8;color:#68552c;padding:12px 16px;margin:18px 0;font-size:12px}.order-heading{margin:28px 0}.finance-columns{display:grid;grid-template-columns:1fr 1fr;gap:54px;margin:35px 0}.finance-columns>section{min-width:0}.term-form{display:grid;gap:18px;margin:24px 0;max-width:520px}.term-form label{display:grid;gap:8px;font-size:12px;color:#596f60}.term-form input,.term-form select,.term-form textarea{box-sizing:border-box;width:100%;font:inherit;padding:11px;border:1px solid #cfdbd2;border-radius:4px;background:#fff;color:#24382f}.term-form textarea{min-height:90px;resize:vertical}.term-form button{justify-self:start}.history article{padding:18px 0;border-bottom:1px solid #e7ece8;font-size:13px;line-height:1.8;overflow-wrap:anywhere;white-space:pre-wrap}.history p{margin:8px 0}.history small{color:#748579}.status-text{font-size:15px!important}.recovery{padding:18px;background:#f7f2e8;border:1px solid #dfcfab;margin-bottom:24px;font-size:13px}.review-dialog{max-height:88vh;overflow:auto}.review-facts dd{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:850px){.finance-columns{grid-template-columns:1fr;gap:20px}.unsaved{align-items:start;flex-direction:column}}
</style>
